added.function:flux_archive_native_grant_guard:
CREATE OR REPLACE FUNCTION public.flux_archive_native_grant_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE g "UserArchiveAssetAccess"; d "ArchiveAccessDecision"; uid text; sid text; av int;
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'Native grants cannot be truncated' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN g:=NEW; ELSE g:=OLD; END IF;
 IF num_nonnulls(g."manualArchiveFileId",g."archivedProjectFileId")>0 AND NOT EXISTS(SELECT 1 FROM "ArchiveAccessDecision" WHERE "recipientId"=g."userId" AND (("sourceKind"='manual' AND "sourceId"=g."manualArchiveFileId") OR ("sourceKind"='project' AND "sourceId"=g."archivedProjectFileId"))) THEN
  IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM "ArchiveAccessDecision" WHERE "recipientId"=NEW."userId" AND (("sourceKind"='manual' AND "sourceId"=NEW."manualArchiveFileId") OR ("sourceKind"='project' AND "sourceId"=NEW."archivedProjectFileId"))) THEN RAISE EXCEPTION 'Cannot replace audited grant identity' USING ERRCODE='23514'; END IF;
  RETURN coalesce(NEW,OLD);
 END IF;
 SELECT * INTO d FROM "ArchiveAccessDecision" WHERE id=current_setting('flux.archive_access_decision',true);
 IF pg_trigger_depth()=2 AND TG_OP IN ('INSERT','DELETE') AND d."grantId"=g.id AND d."recipientId"=g."userId" AND
  d."actorId"=current_setting('flux.archive_access_actor',true) AND d."sessionId"=current_setting('flux.archive_access_session',true) AND
  ((TG_OP='INSERT' AND d.action='GRANT' AND g."grantedById"=d."actorId") OR (TG_OP='DELETE' AND d.action='REVOKE')) AND
  ((d."sourceKind"='runtime' AND g."manualArchiveFileId" IS NULL AND g."archivedProjectFileId" IS NULL) OR (d."sourceKind"='manual' AND g."manualArchiveFileId"=d."sourceId" AND g."archivedProjectFileId" IS NULL) OR (d."sourceKind"='project' AND g."archivedProjectFileId"=d."sourceId" AND g."manualArchiveFileId" IS NULL)) THEN RETURN coalesce(NEW,OLD); END IF;
 uid:=current_setting('flux.archive_delete_actor',true); sid:=current_setting('flux.archive_delete_session',true);
 SELECT "authorizationVersion" INTO av FROM "UserAuthorization" WHERE "userId"=uid;
 IF TG_OP='DELETE' AND pg_trigger_depth()>1 AND coalesce(flux_workflow_actor_current(uid,'DIRECTOR',av,sid),false) AND
  current_setting('flux.archive_delete_id',true)=coalesce(g."manualArchiveFileId",g."archivedProjectFileId") AND
  NOT EXISTS(SELECT 1 FROM "ManualArchiveFile" WHERE id=g."manualArchiveFileId") AND NOT EXISTS(SELECT 1 FROM "ArchivedProjectFile" WHERE id=g."archivedProjectFileId") THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' AND pg_trigger_depth()=2 AND coalesce(flux_workflow_actor_current(uid,'DIRECTOR',av,sid),false) AND EXISTS(SELECT 1 FROM "ArchiveGrantScope" s JOIN "ArchiveAccessDecision" runtime_decision ON runtime_decision.id=s."decisionId" JOIN "RetainedArchiveSource" r ON r."runtimeSourceId"=runtime_decision."sourceId" WHERE s."grantId"=g.id AND runtime_decision."sourceKind"='runtime' AND r."runtimeSourceId"=current_setting('flux.archive_delete_id',true) AND r."actorId"=uid AND r."sessionId"=sid) THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'Audited grant requires confirmed native decision' USING ERRCODE='23514';
END $function$

added.function:flux_archive_runtime_file_guard:
CREATE OR REPLACE FUNCTION public.flux_archive_runtime_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE pub "RuntimeArchivePublication"; ref "SharedFileReference"; uid text; sid text; av int;
BEGIN
 IF TG_OP='INSERT' THEN
  IF EXISTS(SELECT 1 FROM "ManualArchiveFile" WHERE id=NEW.id) OR EXISTS(SELECT 1 FROM "ArchivedProjectFile" WHERE id=NEW.id) OR
   EXISTS(SELECT 1 FROM "RetainedArchiveSource" WHERE "manualSourceId"=NEW.id OR "projectSourceId"=NEW.id OR "runtimeSourceId"=NEW.id) OR
   EXISTS(SELECT 1 FROM "ArchiveAccessDecision" WHERE "sourceId"=NEW.id) THEN RAISE EXCEPTION 'Archive source identity collision' USING ERRCODE='23514'; END IF;
  SELECT * INTO pub FROM "RuntimeArchivePublication" WHERE id=NEW."publicationId";
  IF pg_trigger_depth()<>2 OR NEW."categoryId" IS DISTINCT FROM pub."categoryId" OR pub."actorId" IS DISTINCT FROM current_setting('flux.archive_runtime_actor',true) OR
   NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pub.manifest->'files') WITH ORDINALITY x(item,n) WHERE NEW.id='raf_'||pub.id||'_'||n AND item=jsonb_build_object('submissionId',NEW."submissionId",'referenceId',NEW."referenceId",'versionId',NEW."versionId")) THEN RAISE EXCEPTION 'Confirmed runtime publication required' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 ELSIF TG_OP='DELETE' THEN
  uid:=current_setting('flux.archive_delete_actor',true);sid:=current_setting('flux.archive_delete_session',true);
  SELECT "authorizationVersion" INTO av FROM "UserAuthorization" WHERE "userId"=uid;
  IF current_setting('transaction_isolation')<>'serializable' OR current_setting('flux.archive_delete_id',true) IS DISTINCT FROM OLD.id OR NOT coalesce(flux_workflow_actor_current(uid,'DIRECTOR',av,sid),false) THEN RAISE EXCEPTION 'Current Director deletion required' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT ref FROM "SharedFileReference" WHERE id=OLD."referenceId";
  INSERT INTO "RetainedArchiveSource" (id,"runtimeSourceId","sourceSnapshot","referenceSnapshot","actorId","actorVersion","sessionId") VALUES(ref.id,OLD.id,to_jsonb(OLD),to_jsonb(ref),uid,av,sid);
  DELETE FROM "UserArchiveAssetAccess" g USING "ArchiveGrantScope" s,"ArchiveAccessDecision" d WHERE s."grantId"=g.id AND d.id=s."decisionId" AND d."sourceKind"='runtime' AND d."sourceId"=OLD.id;
  RETURN OLD;
 END IF;
 RAISE EXCEPTION 'Runtime Archive file identity is immutable' USING ERRCODE='23514';
END $function$

added.function:flux_archive_access_source(text:
CREATE OR REPLACE FUNCTION public.flux_archive_access_source(kind text, sid text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE src jsonb; cat text; pid text; rev text; r "SharedFileReference"; v "SharedFileVersion"; f "SharedFile";
BEGIN
 IF kind='runtime' THEN RETURN flux_archive_runtime_source(sid); END IF;
 IF kind='manual' THEN
  SELECT to_jsonb(m),m."archiveCategoryId" INTO src,cat FROM "ManualArchiveFile" m WHERE m.id=sid AND m.status='READY';
  SELECT * INTO r FROM "SharedFileReference" WHERE "manualArchiveFileId"=sid;
 ELSIF kind='project' THEN
  SELECT to_jsonb(a),p."archiveCategoryId",a."projectId",a."sourceRevisionId" INTO src,cat,pid,rev FROM "ArchivedProjectFile" a
   JOIN "ProjectArchive" p ON p.id=a."archiveId" AND p."projectId"=a."projectId"
   JOIN "ProjectAttachment" s ON s.id=a."sourceAttachmentId" AND s."projectId"=a."projectId" AND s.status='READY' AND s.bucket=a.bucket AND s."storageKey"=a."storageKey" AND s."revisionId" IS NOT DISTINCT FROM a."sourceRevisionId" WHERE a.id=sid;
  SELECT * INTO r FROM "SharedFileReference" WHERE "archivedProjectFileId"=sid;
 END IF;
 IF src IS NULL OR NOT EXISTS(SELECT 1 FROM "ArchiveCategory" WHERE id=cat AND "isActive") THEN RETURN NULL; END IF;
 IF r.id IS NOT NULL THEN
  SELECT * INTO STRICT v FROM "SharedFileVersion" WHERE id=r."versionId";
  SELECT * INTO STRICT f FROM "SharedFile" WHERE id=v."fileId";
  IF v.status<>'READY' OR v."objectETag" IS NULL OR (v."objectVersionId" IS NULL AND NOT v."applicationSealed") OR
   v.bucket IS DISTINCT FROM src->>'bucket' OR v."storageKey" IS DISTINCT FROM src->>'storageKey' OR v."fileSize" IS DISTINCT FROM (src->>'fileSize')::int OR v."mimeType" IS DISTINCT FROM src->>'mimeType' OR
   f."projectId" IS DISTINCT FROM pid OR f."flexibleProjectId" IS NOT NULL OR f."runtimeStageId" IS NOT NULL THEN RETURN NULL; END IF;
 END IF;
 RETURN jsonb_build_object('sourceKind',kind,'sourceId',sid,'categoryId',cat,'projectId',pid,'sourceRevisionId',rev,
  'bucket',src->>'bucket','storageKey',src->>'storageKey','fileSize',src->'fileSize','mimeType',src->>'mimeType','referenceId',r.id,'versionId',r."versionId");
END $function$

