  ((d."sourceKind"='runtime' AND g."manualArchiveFileId" IS NULL AND g."archivedProjectFileId" IS NULL) OR (d."sourceKind"='manual' AND g."manualArchiveFileId"=d."sourceId" AND g."archivedProjectFileId" IS NULL) OR
   (d."sourceKind"='project' AND g."archivedProjectFileId"=d."sourceId" AND g."manualArchiveFileId" IS NULL)) AND
  coalesce(d."sourceSnapshot"=flux_archive_access_source(d."sourceKind",d."sourceId"),false);
